package plugin

// pluginLogo is the plugin mark (96x96 PNG) inlined as a data URI so the
// management UI renders it with no extra asset route. It is intentionally
// full-bleed (no baked-in tile, border or rounding): the plugin list draws the
// logo inside its own rounded, bordered box with object-fit: cover, so any
// rounding here would double-frame it.
const pluginLogo = "data:image/png;base64,"
